package com.clavis.reader;
import android.app.*;
import android.content.*;
import android.widget.*;
import org.json.*;
final class PlayerDialogs {
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("playback",0);}
 static void sleep(MainActivity a){new AppDialog.Builder(a).setTitle("Sleep timer").setItems(new String[]{"At the end of this chapter","15 minutes","30 minutes","60 minutes","Custom minutes…","Turn off"},(d,n)->{PlaybackService s=PlaybackService.live;if(s==null)return;if(n==0){s.setSleep(0);s.sleepAtChapterEnd=true;}else if(n==4){EditText input=new EditText(a);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);new AppDialog.Builder(a).setTitle("Sleep after (minutes)").setView(input).setPositiveButton("Set",(dd,nn)->{try{s.setSleep(Math.max(1,Math.min(1440,Integer.parseInt(input.getText().toString()))));}catch(Exception ignored){}}).setNegativeButton("Cancel",null).show();}else s.setSleep(n==1?15:n==2?30:n==3?60:0);AppNotice.makeText(a,n==5?"Sleep timer off":"Sleep timer updated",Toast.LENGTH_SHORT).show();}).setNegativeButton("Close",null).show();}
 static void settings(MainActivity a){String[] labels={"Skip interval","Automatic rewind after pause","Automatically play next book: "+(prefs(a).getBoolean("nextBook",false)?"on":"off"),"Sleep timer","Equalizer & voice gain","Undo last seek","Reset current book position"};new AppDialog.Builder(a).setTitle("Playback settings").setItems(labels,(d,n)->{PlaybackService s=PlaybackService.live;switch(n){case 0:new AppDialog.Builder(a).setTitle("Skip interval").setItems(new String[]{"15 seconds","30 seconds","60 seconds"},(dd,i)->prefs(a).edit().putInt("skip",new int[]{15,30,60}[i]).apply()).show();break;case 1:new AppDialog.Builder(a).setTitle("Rewind on resume").setItems(new String[]{"Off","3 seconds","5 seconds","10 seconds"},(dd,i)->prefs(a).edit().putInt("rewind",new int[]{0,3,5,10}[i]).apply()).show();break;case 2:prefs(a).edit().putBoolean("nextBook",!prefs(a).getBoolean("nextBook",false)).apply();settings(a);break;case 3:sleep(a);break;case 4:if(s!=null&&s.ready)effects(a,s);else AppNotice.makeText(a,"Start an audiobook first",Toast.LENGTH_SHORT).show();break;case 5:if(s!=null)s.undoSeek();break;case 6:if(s!=null)new AppDialog.Builder(a).setTitle("Start this book over?").setPositiveButton("Reset",(dd,i)->s.jumpChapter(0,0)).setNegativeButton("Cancel",null).show();break;}}).setNegativeButton("Close",null).show();}
 static void effects(MainActivity a,PlaybackService s){s.ensureEffects();effects(a,s.equalizer,s.loudness);}
 static void effects(MainActivity a,android.media.audiofx.Equalizer equalizer,android.media.audiofx.LoudnessEnhancer loudness){LinearLayout list=a.column();list.setPadding(a.dp(20),a.dp(10),a.dp(20),0);try{if(equalizer!=null){short[] range=equalizer.getBandLevelRange();for(short band=0;band<equalizer.getNumberOfBands();band++){final short b=band;list.addView(a.text((equalizer.getCenterFreq(band)/1000)+" Hz",13,MainActivity.INK,false));SeekBar slider=new SeekBar(a);AppTheme.tintProgress(slider);slider.setMax(range[1]-range[0]);slider.setProgress(equalizer.getBandLevel(b)-range[0]);slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int p,boolean user){if(user){short level=(short)(p+range[0]);equalizer.setBandLevel(b,level);prefs(a).edit().putInt("eq"+b,level).apply();}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});list.addView(slider);}}list.addView(a.text("Voice gain (0–20 dB)",13,MainActivity.INK,false));SeekBar gain=new SeekBar(a);AppTheme.tintProgress(gain);gain.setMax(20);gain.setProgress(prefs(a).getInt("gain",0));gain.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar bar,int p,boolean user){if(user){prefs(a).edit().putInt("gain",p).apply();if(loudness!=null){loudness.setTargetGain(p*100);loudness.setEnabled(p>0);}}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});list.addView(gain);ScrollView scroll=new ScrollView(a);scroll.addView(list);new AppDialog.Builder(a).setTitle("Equalizer & voice gain").setView(scroll).setPositiveButton("Done",null).show();}catch(Exception e){AppNotice.makeText(a,"Audio effects are unavailable on this output",Toast.LENGTH_SHORT).show();}}
 static String markKey(Book b){return "bookmarks:"+b.uri;}
 static JSONArray marks(MainActivity a,Book b){try{return new JSONArray(a.getSharedPreferences("bookmarks",0).getString(markKey(b),"[]"));}catch(Exception ignored){return new JSONArray();}}
 static void addBookmark(MainActivity a,Book b){PlaybackService s=PlaybackService.live;if(s==null||!s.ready)return;int chapter=s.chapterIndex;long position=s.position();EditText name=new EditText(a);name.setHint("Chapter "+(chapter+1)+" · "+Store.time(position));new AppDialog.Builder(a).setTitle("Add bookmark").setView(name).setPositiveButton("Save",(d,n)->{JSONArray list=marks(a,b);try{list.put(new JSONObject().put("chapter",chapter).put("position",position).put("name",name.getText().toString().trim().isEmpty()?"Chapter "+(chapter+1)+" · "+Store.time(position):name.getText().toString().trim()));a.getSharedPreferences("bookmarks",0).edit().putString(markKey(b),list.toString()).apply();AppNotice.makeText(a,"Bookmark saved",Toast.LENGTH_SHORT).show();}catch(Exception ignored){}}).setNegativeButton("Cancel",null).show();}
 static void chapters(MainActivity a,Book book){PlaybackService s=PlaybackService.live;ChapterWindow.show(a,s!=null&&s.uri.equals(book.uri)&&s.book!=null?s.book:book);}
 static void exportBookmarks(MainActivity a,Book book){Intent send=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_SUBJECT,book.title+" bookmarks").putExtra(Intent.EXTRA_TEXT,marks(a,book).toString());a.startActivity(Intent.createChooser(send,"Export bookmarks"));}
 static void bookmarks(MainActivity a,Book book){JSONArray marks=marks(a,book);String[] labels=new String[marks.length()];for(int i=0;i<labels.length;i++){JSONObject m=marks.optJSONObject(i);labels[i]=m.optString("name")+" · Chapter "+(m.optInt("chapter")+1)+" · "+Store.time(m.optLong("position"));}if(labels.length==0){AppNotice.makeText(a,"No bookmarks yet",Toast.LENGTH_SHORT).show();return;}new AppDialog.Builder(a).setTitle("Bookmarks").setItems(labels,(d,n)->{JSONObject mark=marks.optJSONObject(n);new AppDialog.Builder(a).setTitle(mark.optString("name")).setItems(new String[]{"Go to bookmark","Delete bookmark"},(dd,i)->{if(i==0&&PlaybackService.live!=null)PlaybackService.live.jumpChapter(mark.optInt("chapter"),mark.optLong("position"));else if(i==1){marks.remove(n);a.getSharedPreferences("bookmarks",0).edit().putString(markKey(book),marks.toString()).apply();}}).show();}).setNegativeButton("Close",null).show();}
}
